import asyncio
import aiohttp
import ssl
async def convert_grounding_to_citations(
    grounding_chunks: list[dict]
) -> list[dict]:

    headers = {
        "Content-Type": "application/json",
        "User-Agent": "Tomi/1.0.1 (https://tomi.dev.lspm.io)",
    }

    async with aiohttp.ClientSession(headers=headers) as session:

        async def _fetch_url_once(url: str, method: str) -> str:
            print(f"fetch {url}")
            timeout = aiohttp.ClientTimeout(total=2)
            try:
                #print(f"fetch {url}")
                request = session.head if method == "HEAD" else session.get
                async with request(
                    url, allow_redirects=True, timeout=timeout
                ) as response:
                    if response.status == 404:
                        return "404"
                    return str(response.url)
            except Exception as e:
                return None

        async def fetch_final_url(url: str) -> str:
            #print(f"fetch {url}")
            final_url = await _fetch_url_once(url, "HEAD")
            if not final_url:
                final_url = await _fetch_url_once(url, "GET")
            return final_url

        async def process_chunk(idx, chunk):
            web_info = chunk
            original_url = web_info.get("uri", "")
            title = web_info.get("title", "Unknown Source")
            if not original_url:
                return None
            #print(f"fetch {chunk}")
            final_url = await fetch_final_url(original_url)

            if final_url:
                return {
                    "index": idx,
                    "source_url": final_url,
                    "title": title,
                }
            return {
              "index": idx,
              "source_url": title
            }

        tasks = [
            process_chunk(idx, chunk) 
            for idx, chunk in enumerate(grounding_chunks)
        ]

        results = await asyncio.gather(*tasks)
        #print(f"result : {results}")
    return [res for res in results]

input_data = []
for item in _input.all():
  data = {
    "uri" : item.json.web.uri,
    "title": item.json.web.title
  }
  input_data.append(data)
output = await convert_grounding_to_citations(input_data)
return {
  "output": output
}

