const axios = require('axios');

async function convertGroundingToCitations(groundingChunks) {
  const headers = {
    "Content-Type": "application/json",
    "User-Agent": "Tomi/1.0.1 (https://tomi.dev.lspm.io)",
  };

  async function fetchUrlOnce(url, method) {
    try {
      console.log(`fetch [${method}] ${url}`);
      const response = await axios({
        method: method,
        url: url,
        headers: headers,
        timeout: 2000,
        // CHÌA KHÓA Ở ĐÂY: Cho phép nhận tất cả các status code từ 200 đến 499 
        // mà không ném ra lỗi (bỏ qua bước tạo AxiosError lỗi của thư viện)
        validateStatus: function (status) {
          return status >= 200 && status < 500; 
        },
      });

      // Nếu gặp 404 hoặc các lỗi chặn quyền như 403, coi như không lấy được URL final
      if (response.status === 404 || response.status === 403) {
        return null;
      }

      // Đảm bảo responseUrl tồn tại trước khi lấy
      return response.request?.res?.responseUrl || url;
    } catch (error) {
      // Bọc thêm một lớp an toàn nếu vẫn có lỗi kết nối (Timeout, Network Error)
      console.log(`Fetch error for ${url}:`, error.message || error);
      return null;
    }
  }

  async function fetchFinalUrl(url) {
    let finalUrl = await fetchUrlOnce(url, 'HEAD');
    if (!finalUrl) {
      finalUrl = await fetchUrlOnce(url, 'GET');
    }
    return finalUrl;
  }

  async function processChunk(idx, chunk) {
    const webInfo = chunk.json?.web || {};
    const originalUrl = webInfo.uri || '';
    const title = webInfo.title || 'Unknown Source';

    if (!originalUrl) {
      return null;
    }

    const finalUrl = await fetchFinalUrl(originalUrl);

    if (finalUrl) {
      return {
        citation_index: idx,
        citation_url: finalUrl,
        citation_title: title,
      };
    }

    return {
      citation_index: idx,
      citation_url: title,
    };
  }

  const tasks = groundingChunks.map((chunk, idx) => processChunk(idx, chunk));
  const results = await Promise.all(tasks);
  console.log("result: " + JSON.stringify(results));
  return results.filter((res) => res);
}

// Thực thi chính trong n8n
const final = await convertGroundingToCitations($input.all());
return {
  output: final
};

